const input = { ...$json };

const query = String(input.query || input.search_query || input.keyword || '').trim();
const location = String(input.location || '').trim();

if (!query) {
  throw new Error('LEAD_GEN_QUERY_MISSING');
}

if (!location) {
  throw new Error('LEAD_GEN_LOCATION_MISSING');
}

return [{
  json: {
    ...input,
    query,
    location
  }
}];

return items.map(item => {
  const data = item.json;

  return {
    json: {
      name: data.name ?? data.business_name ?? data.company_name ?? null,
      phone: data.phone ?? data.phone_number ?? null,
      email: data.email ?? null,
      website: data.website ?? data.domain ?? data.url ?? null,
      source: data.source ?? 'lead_generation_agent'
    }
  };
});

const data = $json;
const results = Array.isArray(data.results) ? data.results : null;

if (results && results.length === 0) {
  return [{
    json: {
      ...data,
      success: false,
      error_type: 'NO_RESULTS',
      source: 'lead_generation_agent',
      results_count: 0
    }
  }];
}

return [{
  json: {
    ...data,
    success: true,
    error_type: null,
    source: data.source ?? 'lead_generation_agent'
  }
}];
